<div class="page-header"><div><p class="eyebrow">ENROLMENT</p><h1><?= $user['role_slug']==='student'?'My course registration':'Course registrations' ?></h1><p>Each record is linked to a course, semester and student.</p></div></div>
<?php if($user['role_slug']==='student'):?><section class="panel mb-4"><div class="panel-heading"><h2>Available courses</h2><span class="subtle-tag"><?= e($semester?($semester['session_name'].' · Semester '.$semester['semester_number']):'No active semester') ?></span></div>
<?php if(!$semester):?><p class="empty-state">Registration is unavailable until an academic session and semester are active.</p><?php else:?><p class="form-hint">Registration is allowed only during the configured date window. Prerequisites must be verified from published grades.</p><div class="table-scroll"><table class="table table-clean"><thead><tr><th>Code</th><th>Title</th><th>Units</th><th></th></tr></thead><tbody><?php foreach($eligible as $r):?><tr><td><strong><?= e($r['code']) ?></strong></td><td><?= e($r['title']) ?></td><td><?= (int)$r['credit_units'] ?></td><td><form method="post" action="/enrollments/add"><?= csrf_field() ?><input type="hidden" name="course_id" value="<?= (int)$r['id'] ?>"><button class="btn btn-primary btn-sm">Register</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php endif; ?>
<section class="panel"><h2><?= $user['role_slug']==='student'?'My registration history':'Recent registrations' ?></h2><div class="table-scroll"><table class="table table-clean"><thead><tr><?php if($user['role_slug']!=='student'):?><th>Student</th><th>Matric no.</th><?php endif; ?><th>Course</th><th>Status</th><?php if($user['role_slug']==='student'):?><th>Action</th><?php endif; ?></tr></thead><tbody><?php foreach($items as $r):?><tr><?php if($user['role_slug']!=='student'):?><td><?= e($r['full_name']) ?></td><td><?= e($r['matriculation_number']) ?></td><?php endif; ?><td><?= e($r['code'].' · '.($r['title']??'')) ?></td><td><span class="status-pill <?= e($r['status']) ?>"><?= e($r['status']) ?></span></td><?php if($user['role_slug']==='student'):?><td><?php if($r['status']==='registered' && $semester && (int)$r['semester_id']===(int)$semester['id']):?><form method="post" action="/enrollments/drop"><?= csrf_field() ?><input type="hidden" name="course_id" value="<?= (int)$r['course_id'] ?>"><button class="btn btn-outline-secondary btn-sm">Drop</button></form><?php endif; ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?= page_links($page,$total,'/enrollments') ?></section>
